#include<cstdio>
int n,m,a[500005];
int dfs(int b,int c,int sum){
    if(sum==0)return -1;
    if(c==m)return sum;
    if(b>n)return -1;
    int d=dfs(b+1,c,sum);
    int e=dfs(b+1,c+1,sum&a[b]);
    if(d<e){
        return e;
    }else{
        return d;
    }
}
int main(){
    freopen("and.in","r",stdin);
    freopen("and.out","w",stdout);
    scanf("%d%d",&n,&m);
    for(int i=1;i<=n;i++){
        scanf("%d",&a[i]);
    }
    int ans=dfs(1,0,2147483647);
    if(ans==-1){
        ans=0;
    }
    printf("%d",ans);
    return 0;
}

